public final float scanFieldFloat(char[] fieldName) {
    matchStat = UNKNOWN;

    if (!charArrayCompare(fieldName)) {
        matchStat = NOT_MATCH_NAME;
        return 0;
    }

    int offset = fieldName.length;
    char chLocal = charAt(bp + (offset++));

    final boolean quote = chLocal == '"';
    if (quote) {
        chLocal = charAt(bp + (offset++));
    }

    int start = bp + fieldName.length;
    int count = 0;
    boolean isNegative = false;

    if (chLocal == '-') {
        isNegative = true;
        chLocal = charAt(bp + (offset++));
    }

    while (chLocal >= '0' && chLocal <= '9' || chLocal == '.' || chLocal == 'e' || chLocal == 'E' || chLocal == '+' || chLocal == '-') {
        chLocal = charAt(bp + (offset++));
        count++;
    }

    if (quote && chLocal == '"') {
        chLocal = charAt(bp + (offset++));
    } else if (quote) {
        matchStat = NOT_MATCH;
        return 0;
    }

    if (count == 0) {
        matchStat = NOT_MATCH;
        return 0;
    }

    try {
        String text = subString(start, count);
        // Use BigDecimal for precise float parsing
        BigDecimal bigDecimalValue = new BigDecimal(text);
        float value = bigDecimalValue.floatValue();

        if (chLocal == ',') {
            bp += offset;
            this.ch = charAt(bp);
            matchStat = VALUE;
            token = JSONToken.COMMA;
            return value;
        }

        if (chLocal == '}') {
            chLocal = charAt(bp + (offset++));
            if (chLocal == ',') {
                token = JSONToken.COMMA;
                bp += offset;
                this.ch = charAt(bp);
            } else if (chLocal == ']') {
                token = JSONToken.RBRACKET;
                bp += offset;
                this.ch = charAt(bp);
            } else if (chLocal == '}') {
                token = JSONToken.RBRACE;
                bp += offset;
                this.ch = charAt(bp);
            } else if (chLocal == EOI) {
                bp += (offset - 1);
                token = JSONToken.EOF;
                ch = EOI;
            } else {
                matchStat = NOT_MATCH;
                return 0;
            }
            matchStat = END;
        } else {
            matchStat = NOT_MATCH;
            return 0;
        }
        return value;
    } catch (NumberFormatException e) {
        matchStat = NOT_MATCH;
        return 0;
    }
}
